	zip.Describe("github.com/hanzoai/cloud/apps/research GET /v1/research/runs", zip.Doc{
		Description: "Returns the caller org's recorded executions with their\nderived completion. ?id= narrows to one, which is how a single run is read;\n?benchmark=, ?system=, ?study=, ?since= and ?until= narrow the rest; and\n?completion=partial is the query this record was built to answer — which runs\nwere reported before they finished.\n\n?key= is the read a harness makes before it spends: every run carries `key`,\nthe sha256 of what decides its number (benchmark, split, system, version, k,\ntemperature, max_tokens, embedder, reader and the four digests), and a\ncomplete run under the key it is about to measure is a measurement already\nheld. With ?completion=complete beside it the answer is empty or the hit.\n\nEvery listing also answers how much of itself is recorded: `completion` counts\nthe matched runs by the four completion values, and `gaps` names each field\nsome matched run leaves unstated with how many leave it unstated. Both are\ncomputed over the runs the filter matched, so narrowing the listing narrows\nthe account of it.\n\n?id= and ?benchmark= each take a comma-separated list, any of which a run may\nmatch. ?category= and ?metric= narrow each run's measures to the slices and\nquantities named, and drop no run. ?view=summary serves each run with what a\npage draws and nothing a harness re-runs it from. The listing comes in pages\nof ?limit= runs (1 to 200, 100 when it names none) in its order, project then\nid: `total` counts every matched run, and `next`, passed back as ?cursor= with\nthe same query, reads the page after; the last page carries none.\n\nA caller with no org of its own, no credential at all, reads the runs the org\n`?org=` names granted public (POST /v1/research/grants) and no others. Until\nthat org has published a run the answer is the 404 an address nobody serves\ngets, so the read tells nobody which orgs use research; after, a private run is\nabsent from the listing exactly as a run never recorded is. That read serves an\nEnso or Zen run without its version, notes, prompt, embedder or reader, an\nenso.* benchmark's runs without notes, and no run of the base models those\nfamilies and Kai are built from; its `key` is derived over what it serves. The\norg's own read is the full record.",
		Fields: map[string]string{
			"Census.complete":         "Complete: the run says it answered every question it set out to and says\nwhen it ended.",
			"Census.inconsistent":     "Inconsistent: the run's own two counts cannot both be true.",
			"Census.partial":          "Partial: the run says it answered fewer. A number taken from one of\nthese was taken from a checkpoint.",
			"Census.unknown":          "Unknown: the run does not establish completion. This is the common case\nfor anything recorded before a lane wrote its counts, and it is reported\nrather than rounded toward either of the other three.",
			"Gap.field":               "Field is the run field, by its wire name — so a reader goes straight\nfrom this list to the field on the run that is missing.",
			"Gap.runs":                "Runs is how many of the runs do not state it.",
			"Measure.category":        "Category is the slice of the run's items this number covers: all, dev,\ntest, multi-hop, mh_32k. \"all\" is the whole run.",
			"Measure.hi":              "Hi is the high end of that same interval. Null on the same terms as Lo.",
			"Measure.lo":              "Lo is the low end of the interval the harness reported around Value.\nNull means it reported none — NOT an interval of zero width, which is\nwhat a bare 0 would claim.",
			"Measure.metric":          "Metric is the quantity — f1, em, recall@10, substring_em. It is the only\nplace Value's unit is stated; nothing here normalizes, so one harness's\n0.45 and another's 45.1 are both stored as reported and are comparable\nonly within one (benchmark, metric).",
			"Measure.n":               "N is how many items this number was computed over. Null means the\nharness did not say, which is the difference between a wide interval and\nan unknown one.",
			"Measure.of":              "Of is how many items the category HOLDS — the denominator N is drawn\nfrom. Null means the harness did not say. N far below Of on a run whose\ncompletion reads complete is the sign of a category the run skipped\nrather than failed.",
			"Measure.value":           "Value is the number, in whatever unit Metric names.",
			"MeasureSummary.category": "Category is the slice of the run's items this number covers.",
			"MeasureSummary.hi":       "Hi is the high end of that interval. Absent when it reported none.",
			"MeasureSummary.lo":       "Lo is the low end of the interval the harness reported. Absent when it\nreported none.",
			"MeasureSummary.metric":   "Metric is the quantity, and the only place Value's unit is stated.",
			"MeasureSummary.n":        "N is how many items this number was computed over. Absent when the\nharness did not say.",
			"MeasureSummary.of":       "Of is how many items the category holds. Absent when the harness did not\nsay.",
			"MeasureSummary.value":    "Value is the number, in whatever unit Metric names.",
			"Run.answered":            "Answered is how many of them it actually answered. Null means the record\ndoes not say. Below Questions the run is partial; above it the two\ncounts contradict each other and the run is inconsistent.",
			"Run.baseline":            "Baseline marks a run as the reference the others are read against. It\nchanges nothing about how the run is stored or compared; it is how a\nboard knows which line to draw first.",
			"Run.benchmark":           "Benchmark is the ResearchBenchmark id this run measured against. Nothing\nchecks that the definition is recorded — a run may be filed before its\nbenchmark is — but a comparison across two different values here is\nrefused.",
			"Run.by":                  "By names who ran it: the person, the job, the fleet. Empty means the\nrecord does not say.",
			"Run.canonical":           "Canonical is DERIVED on read, never stored: a version is canonical when\nit is the latest-appended non-retracted version of its id.",
			"Run.commit":              "Commit is the commit the harness was frozen at. Together with the\ndigests above and the knobs beside them it is what \"re-runnable from its\nown record\" means.",
			"Run.completion":          "Completion is DERIVED on read from Questions, Answered and Ended, and is\nnever stored or taken from a write: complete, partial, inconsistent or\nunknown. It is the field a published number must be checked against.",
			"Run.dataset_digest":      "DatasetDigest is the sha256 of the dataset the run scored against. It is\nthe strongest single guard on comparability: two runs over different\ndataset digests measured different items.",
			"Run.embedder":            "Embedder is the embedding model the run retrieved with. Empty means the\nrecord does not say, or the run retrieved nothing.",
			"Run.ended":               "Ended is when it stopped, RFC3339. Empty means the record does not say\nit ever did — which alone keeps completion at unknown, however well the\ncounts agree.",
			"Run.facts_digest":        "FactsDigest is the sha256 of the extracted-fact layer the run retrieved\nover, for runs that have one.",
			"Run.id":                  "ID is the run's stable id — the run directory's name by convention,\n`<benchmark>-<split>-<config>-<system>`, carrying no date. It is the key\nversions accrue under: a correction re-sent with this id appends a new\nversion beside the old rather than replacing it, which is how a run\npublished from a checkpoint is fixed without erasing what was published.\nRequired on a write.",
			"Run.k":                   "K is the retrieval depth. Null means the record does not say — never 0,\nwhich would claim the run retrieved nothing.",
			"Run.key":                 "Key is the measurement's identity, DERIVED on read and never taken from\na write: sha256 over what decides the number — benchmark, split, system,\nversion, k, temperature, max_tokens, embedder, reader and the four\ndigests — and over nothing about who ran it, when, at which commit or\nwhat it found. Two runs with one key measured the same thing, so a\nharness asks ?key= before it spends and measures again only when told to.",
			"Run.max_tokens":          "MaxTokens is the reader's answer cap. Null means the record does not\nsay.",
			"Run.measures":            "Measures are the run's numbers, one row per (category, metric), with the\nintervals the harness reported.",
			"Run.notes":               "Notes is anything about this execution a reader needs that no field\nabove carries — a fallback that was hit, a category that was skipped.",
			"Run.project":             "Project is the sub-scope inside the org this run is filed under. On a\nwrite it is the SERVER's value — the caller's project scope — and a\nproject sent in the body is ignored.",
			"Run.prompt":              "Prompt is the prompt FILE the run read, by path. The file is what makes\na prompt reproducible; the digest below is what makes it checkable.",
			"Run.prompt_digest":       "PromptDigest is the sha256 of that file's bytes as the harness recorded\nit. Two runs whose prompt digests differ read different instructions,\nwhatever their prompt paths say.",
			"Run.publishable":         "Publishable is consent to publish this run to the commons. A write forces\nfalse; only a grant sets it.",
			"Run.questions":           "Questions is how many questions the run set out to answer — the\nDENOMINATOR. Null means the record does not say, and a run that does not\nsay cannot be shown as finished. This field and the next are why this\ntype exists.",
			"Run.reader":              "Reader is the model that produced the answers. Empty means the record\ndoes not say; the literal `none` means the run measured retrieval and\nread nothing.",
			"Run.revision":            "Revision is this version's declared kind: original, corrected or\nretracted. Anything else, including empty, reads as original. A\nretracted latest version WITHDRAWS the id; every earlier version stays\nretained.",
			"Run.split":               "Split is which of the benchmark's declared splits the run covered.\nEmpty means the record does not say, and two runs cannot be compared\nacross differing splits.",
			"Run.store_digest":        "StoreDigest is the sha256 of the retrieval store the run queried —\nthe index, with whatever was in it.",
			"Run.study":               "Study is the Study id this run belongs to, when it belongs to one. A run\nnames its study; it never names a paper.",
			"Run.system":              "System is what was under test — the model, the engine, the retrieval\npolicy. A baseline names its system here like any other run:\n`naive-rag` is a system that was measured, never a category inside\nsomebody else's numbers. Empty means the record does not say, which a\ncomparison treats as a reason not to compare rather than as a match.",
			"Run.temperature":         "Temperature is the reader's sampling temperature. Null means the record\ndoes not say — never 0, which is a deliberate and common setting and so\nthe most expensive possible default.",
			"Run.trainable":           "Trainable is consent to train on this run. A write forces false; only a\ngrant sets it. Recording a run conveys no training right.",
			"Run.version":             "Version is the system's own version at the time it was measured. Empty\nmeans the record does not say, and two runs of one system at unrecorded\nversions are not known to be two runs of the same thing.",
			"Run.visibility":          "Visibility is private, org or public. A write forces private whatever the\nbody says; only a grant moves it.",
			"Run.when":                "When is when the run started, RFC3339. Empty means the record does not\nsay. It is what ?since= and ?until= bound a listing by.",
			"RunSummary.answered":     "Answered is how many of them it answered. Null means the record does not\nsay.",
			"RunSummary.baseline":     "Baseline marks the run the others are read against.",
			"RunSummary.benchmark":    "Benchmark is the task the run measured against.",
			"RunSummary.canonical":    "Canonical is true on every row a listing answers with.",
			"RunSummary.commit":       "Commit is the commit the harness was frozen at.",
			"RunSummary.completion":   "Completion is derived from Questions, Answered and Ended: complete,\npartial, inconsistent or unknown.",
			"RunSummary.ended":        "Ended is when the run stopped, RFC3339. Empty means the record does not\nsay it ever did.",
			"RunSummary.id":           "ID is the run's stable id.",
			"RunSummary.measures":     "Measures are the run's numbers, narrowed as the query asked.",
			"RunSummary.notes":        "Notes is anything about the execution no field above carries.",
			"RunSummary.project":      "Project is the sub-scope inside the org the run is filed under.",
			"RunSummary.questions":    "Questions is how many questions the run set out to answer. Null means the\nrecord does not say.",
			"RunSummary.revision":     "Revision is this version's declared kind: original, corrected or\nretracted.",
			"RunSummary.split":        "Split is which of the benchmark's splits the run covered. Empty means the\nrecord does not say.",
			"RunSummary.study":        "Study is the study the run belongs to, when it belongs to one.",
			"RunSummary.system":       "System is what was under test. Empty means the record does not say.",
			"RunSummary.version":      "Version is the system's version when it was measured. Empty means the\nrecord does not say.",
			"RunSummary.visibility":   "Visibility is private, org or public.",
			"runsIn.benchmark":        "Benchmark narrows to the runs measured against these tasks: one, or\nseveral separated by commas, any of which a run may have measured.",
			"runsIn.category":         "Category keeps, of each run's measures, those whose category is one of\nthese (comma-separated) or lies under one: `vs-claude-code` keeps\n`vs-claude-code/search`. It narrows a run's measures and never drops the\nrun.",
			"runsIn.completion":       "Completion narrows by the DERIVED completion: complete, partial,\ninconsistent or unknown. `partial` is the query that finds runs whose\nnumbers were published before they finished. Anything outside those four\nis refused rather than quietly matching nothing.",
			"runsIn.cursor":           "Cursor continues a listing: pass back the previous page's `next`, with the\nsame query. Omit it for the first page.",
			"runsIn.id":               "ID narrows to the runs with these ids: one, which is how a single run is\nread, or several separated by commas, any of which a run may carry.",
			"runsIn.key":              "Key narrows to the runs of one measurement identity — the derived `key`\na run carries, which a client computes the same way before it spends.\nA complete run here is a measurement already paid for.",
			"runsIn.limit":            "Limit is how many runs one page carries, 1 to 200. Absent or 0, it is\n100: a listing longer than that is read by its `next`.",
			"runsIn.metric":           "Metric keeps, of each run's measures, those whose metric is one of these\n(comma-separated). It narrows a run's measures and never drops the run.",
			"runsIn.org":              "Org is the org whose runs a caller with no org of its own reads, and then\nonly the runs that org granted public. A caller with an org reads its own,\nand this is not consulted.",
			"runsIn.project":          "Project narrows to one project. Empty reads the org's whole set.",
			"runsIn.since":            "Since bounds the listing to runs that STARTED at or after this RFC3339\ninstant. A run whose start is unrecorded never satisfies a bounded\nfilter — an unknown date is not evidence of falling in a range.",
			"runsIn.study":            "Study narrows to the runs belonging to one study.",
			"runsIn.system":           "System narrows to the runs of one system under test — which is also how\na baseline's runs are listed, since a baseline is a system that was run.",
			"runsIn.until":            "Until bounds the listing to runs that started at or before this RFC3339\ninstant, on the same terms as Since.",
			"runsIn.view":             "View is how much of each run the answer carries. Empty is the full record.\n`summary` is what a page draws: each run without its key, digests, prompt,\nembedder, reader, k, temperature, max_tokens, when, by, trainable or\npublishable, each measure without the interval and counts it does not\nstate, and the listing without gaps. Anything else is refused.",
			"runsOut.completion":      "Completion counts the matched runs, across every page, by completion.\nRead it before reading any aggregate over Data: a set whose Unknown or\nPartial is a large share of Total is a set whose average is over runs\nthat may not have finished.",
			"runsOut.data":            "Data are the canonical runs, each with its derived completion, ordered\nby project then id: one page of them.",
			"runsOut.gaps":            "Gaps is one field per entry that some matched run leaves unstated, with\nhow many leave it unstated, worst first. It is the record's account of\nits own incompleteness, and it is answered on every listing rather than\ndiscovered by reading the rows: a field nobody records is a comparison\nnobody can make.",
			"runsOut.next":            "Next continues the listing: pass it back as `cursor`. Absent on the last\npage.",
			"runsOut.total":           "Total is how many runs the query matched, across every page.",
			"runsSummary.completion":  "Completion counts the matched runs, across every page, by completion.",
			"runsSummary.data":        "Data are the canonical runs, ordered by project then id, each as the\nsummary view serves it: one page of them.",
			"runsSummary.next":        "Next continues the listing: pass it back as `cursor`. Absent on the last\npage.",
			"runsSummary.total":       "Total is how many runs the query matched, across every page.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research GET /v1/research/standard", zip.Doc{
		Description: "Returns the HIP-1400 component conformance manifest for\nthe research, evolution, evidence, and XP plane.",
		Fields: map[string]string{
			"ImplementedHIP.hip":                "HIP is the four-digit zero-padded HIP identifier (for example \"1401\").",
			"ImplementedHIP.status":             "Status is conformant or partial.",
			"ImplementedHIP.version":            "Version is the semantic version of that HIP's contract implemented here.",
			"StandardManifest.capabilities":     "Capabilities lists the HIP-0139 capability identifiers served here.",
			"StandardManifest.component":        "Component is the canonical layer and component identifier (research/cloud).",
			"StandardManifest.implemented_hips": "ImplementedHIPs lists every HIP specification this component implements.",
			"StandardManifest.spec_version":     "SpecVersion is the target Hanzo OS standard.json semantic version.",
			"StandardManifest.version":          "Version is this component's semantic release version.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research GET /v1/research/studies", zip.Doc{
		Description: "Returns the caller org's studies — the question each set\nof runs was run to answer and what it found. ?id= narrows to one.",
		Fields: map[string]string{
			"ImprovementMetric.category":          "Category is the measure's category, exactly as recorded in the run.",
			"ImprovementMetric.direction":         "Direction is higher or lower; improvement is signed in this direction.",
			"ImprovementMetric.max_regression":    "MaxRegression is the greatest permitted degradation for this metric.",
			"ImprovementMetric.metric":            "Metric is the measure's name, exactly as recorded in the run.",
			"ImprovementMetric.min_gain":          "MinGain is the primary metric's required absolute gain in its own units.",
			"ImprovementPolicy.baseline":          "Baseline is the reference run id, in this study's project and study.",
			"ImprovementPolicy.metrics":           "Metrics are the objective followed by optional regression guardrails.",
			"ImprovementPolicy.min_questions":     "MinQuestions is the minimum completed evaluation size (at least one).",
			"ImprovementPolicy.require_intervals": "RequireIntervals blocks a verdict unless both runs report non-overlapping\nintervals for the primary metric. Intervals must use the same method.",
			"ImprovementPolicy.target":            "Target names the harness, app, skill, connector or infrastructure under test.",
			"Study.canonical":                     "Canonical is DERIVED on read: the latest-appended non-retracted version\nof this id.",
			"Study.finding":                       "Finding is what the runs showed, once they had. Empty while the study is\nopen — and a finding recorded before the runs completed is the failure\nthis whole record exists to make visible.",
			"Study.id":                            "ID is the study's stable id, a slug. Runs name it in their `study`.\nRequired on a write.",
			"Study.improvement":                   "Improvement enables automatic, deterministic review of this study's runs.\nEvery candidate is compared with the named baseline using these declared\nmetrics; results become private DRAFT research actions, never deployments.",
			"Study.project":                       "Project is the sub-scope inside the org this study is filed under — the\nSERVER's value on a write.",
			"Study.question":                      "Question is what it set out to answer, in a sentence. A study without\none is a folder.",
			"Study.revision":                      "Revision is this version's declared kind: original, corrected or\nretracted, on the same terms as every other record here.",
			"Study.title":                         "Title is what the study is called.",
			"Study.when":                          "When is when the study was opened, RFC3339. Empty means the record does\nnot say.",
			"studiesIn.id":                        "ID narrows to exactly one study, which is how a single study is read.",
			"studiesIn.project":                   "Project narrows to one project. Empty reads the org's whole set.",
			"studiesOut.data":                     "Data are the canonical studies, ordered by project then id.",
			"studiesOut.total":                    "Total is len(data).",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research GET /v1/research/totals", zip.Doc{
		Description: "Returns the caller org's headline aggregate plus a per-kind\nbreakdown — the observatory's poll target. Canonical and retained counts travel\ntogether, so a deduped view never reads as loss. ?project= narrows to one project.",
		Fields: map[string]string{
			"KindTotal.cost_usd":                  "CostUSD is US DOLLARS (not cents) summed over those same runs.",
			"KindTotal.experiments":               "Experiments counts the canonical answered runs of this kind — the same\npredicate as the headline count, sliced.",
			"KindTotal.kind":                      "Kind is the discriminator this row aggregates: benchmark, kernel-perf,\ntraining, ablation, policy-eval, ab. A kind appears as soon as any RETAINED\nversion carries it, so a kind whose every run was retracted or faulted is\nlisted with zero experiments rather than dropped.",
			"ResearchTotals.attempts":             "Attempts counts the CANONICAL answered attempts, one per (benchmark, item,\nmodel).",
			"ResearchTotals.attempts_retained":    "AttemptsRetained counts every attempt version held, on the same terms as\nExperimentsRetained.",
			"ResearchTotals.benchmarks":           "Benchmarks is how many DISTINCT benchmarks those same attempts cover.",
			"ResearchTotals.by_kind":              "ByKind is the same headline split per discriminator, ordered by kind.",
			"ResearchTotals.cost_usd":             "CostUSD is US DOLLARS (not cents) summed over the canonical answered runs.",
			"ResearchTotals.experiments":          "Experiments counts the CANONICAL answered runs: one per stable id, the\nlatest non-retracted version, faulted and failed left out.",
			"ResearchTotals.experiments_retained": "ExperimentsRetained counts every run version held — superseded and\nretracted included. Retained is always ≥ canonical, and the gap is history\nrather than loss, which is why both travel together.",
			"ResearchTotals.models":               "Models is how many DISTINCT models appear across the canonical answered\nattempts.",
			"ResearchTotals.project":              "Project echoes the project the aggregate was narrowed to. Absent means the\nfigures below span the whole org.",
			"ResearchTotals.projects":             "Projects is how many DISTINCT projects the counted evidence spans, so it is\n1 whenever Project narrows to one.",
			"totalsIn.project":                    "Project narrows the aggregate to one project. Empty aggregates the whole org.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research GET /v1/research/xp", zip.Doc{
		Description: "GetResearchXP computes the deterministic, non-transferable Hanzo XP read\nprojection (HIP-1402) from canonical qualified EvolutionCandidates and\nindependently replicated confirmatory ResearchClaims. Unqualified proposals,\nexploratory runs, and unreplicated claims yield strictly zero XP, and any\nretracted claim or candidate emits a compensating negative projection that\nreverses the credit to net zero.",
		Fields: map[string]string{
			"XPBalance.domains":          "Domains maps each active skill domain (harness, engine, model, sandbox,\nscience, spec) to its net verified integer XP.",
			"XPBalance.principal":        "Principal is the human or agent identity whose verified reputation this summarizes.",
			"XPBalance.total_xp":         "TotalXP is the sum of net verified XP across all six domains.",
			"XPProjection.candidate_ref": "CandidateRef is the EvolutionCandidate or ResearchClaim digest that earned\nor lost this XP.",
			"XPProjection.delta":         "Delta is the signed integer XP change (positive on verified qualification\nor replication, negative on retraction reversal).",
			"XPProjection.domain":        "Domain is one of the six closed skill domains: harness, engine, model,\nsandbox, science, or spec.",
			"XPProjection.effective_at":  "EffectiveAt is the RFC 3339 UTC timestamp of the underlying verification or retraction.",
			"XPProjection.evidence_ref":  "EvidenceRef is the Evidence or Run digest backing this XP entry.",
			"XPProjection.principal":     "Principal is the human or agent identity receiving this non-transferable delta.",
			"XPProjection.projection_id": "ProjectionID is the deterministic sha256:<hex> digest of\n(evidence_ref, principal, domain, reason, rule_version).",
			"XPProjection.reason":        "Reason is candidate_qualified, claim_replicated, conformance_resolved, or retracted.",
			"XPProjection.retracted_by":  "RetractedBy names the CounterEvidence digest when this credit was reversed,\nor null/empty while active.",
			"XPProjection.rule_version":  "RuleVersion is the semantic version of the pure XP projection function (\"1.0.0\").",
			"xpIn.domain":                "Domain narrows to one skill domain (harness, engine, model, sandbox, science, spec).",
			"xpIn.principal":             "Principal narrows to one principal (did:hanzo:... or user id).",
			"xpIn.project":               "Project narrows the projection to one project; empty folds the whole org.",
			"xpOut.balances":             "Balances lists per-principal domain XP totals sorted by total_xp descending.",
			"xpOut.non_transferable":     "NonTransferable is always true: Hanzo XP is soulbound reputation, never a\ntransferable token or currency (HIP-1402 §1).",
			"xpOut.projections":          "Projections lists every deterministic XPProjection event folded into Balances.",
			"xpOut.rule_version":         "RuleVersion is the semantic version of the deterministic projection rules (\"1.0.0\").",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research POST /research/evidence/record", zip.Doc{
		Description: "Is Record across the peer plane: the tenant always comes from\nthe authenticated context. It accepts observations, never probe endpoints.",
		Fields: map[string]string{
			"ResearchEvidenceIn.experiments":    "Experiments is the array of research Experiment records, without endpoints.",
			"ResearchEvidenceIn.project":        "Project is the experiment's project within the caller's org.",
			"ResearchEvidenceRecorded.recorded": "Recorded is the number of newly appended evidence versions.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research POST /v1/research/actions", zip.Doc{
		Description: "Files a DDT Action as a DRAFT, with who it is assigned to. Anyone\nmay: Kai, an agent, a person. The DDT Action's own status, when it has one, is\nDRAFT, and it carries no authorizedBy or authorizedAt (422); an action is\nauthorized by a person, never filed so. Filing it again\nwith other content or another assignee files its next state, with a new hash;\nan action a person has authorized is not replaced by a draft (409).",
		Fields: map[string]string{
			"Action.action":       "Action is the DDT Action, verbatim: id, decisionId, status, verdict, rule,\ndescription. Its id is required; its status, when present, must be DRAFT;\nand it carries no authorizedBy or authorizedAt, which are the server's.\nAuthorizing writes AUTHORIZED into it.",
			"Action.assignee":     "Assignee is who the action is assigned to.",
			"Action.authorizedAt": "AuthorizedAt is when it was authorized, RFC 3339 UTC. The server's.",
			"Action.authorizedBy": "AuthorizedBy is the person who authorized it. The server's.",
			"Action.by":           "By is the user who filed this state. The server's.",
			"Action.decisionId":   "DecisionID is the DDT Action's decisionId. DERIVED by the server.",
			"Action.hash":         "Hash is this state's content hash, lowercase hex, over the DDT Action, the\nassignee and the authorization. Authorizing names it, so a person\nauthorizes the state they read. The server's.",
			"Action.id":           "ID is the action's record id, `act_` and 32 hex digits, one per DDT Action\nid. The server's.",
			"Action.status":       "Status is DRAFT until a person authorizes the action, then AUTHORIZED. The\nserver's: a write files DRAFT, and a DRAFT never replaces an AUTHORIZED\naction.",
			"Action.time":         "Time is when this state of the action was filed, RFC 3339 UTC. The\nserver's.",
		},
		Example: json.RawMessage(`{"action":{"id":"RUN_KAI_08B02A2DE43C89D7/anchor","decisionId":"DEC-SPH-0412","status":"DRAFT","verdict":"ask","rule":"kai.anchor","description":"Does the charter favor one option before the options were measured?"},"assignee":"ada@army.mil"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research POST /v1/research/actions/:id/authorize", zip.Doc{
		Description: "Moves an action to AUTHORIZED, the state the person read: the\nrequest names that state's hash, and an action that has changed since — refiled\nby an agent, or authorized by someone else — is refused 409. The read and the\nwrite are one transaction, so of two people authorizing one draft at once one\nis answered and the other refused 409. It writes AUTHORIZED into the stored DDT\nAction and stamps the person who authorized it and when. Only a person signed\nin with their own token, in their own org, may: an API key, an application or\nan agent acting for someone is refused 403. The draft it replaces is kept.",
		Fields: map[string]string{
			"Action.action":       "Action is the DDT Action, verbatim: id, decisionId, status, verdict, rule,\ndescription. Its id is required; its status, when present, must be DRAFT;\nand it carries no authorizedBy or authorizedAt, which are the server's.\nAuthorizing writes AUTHORIZED into it.",
			"Action.assignee":     "Assignee is who the action is assigned to.",
			"Action.authorizedAt": "AuthorizedAt is when it was authorized, RFC 3339 UTC. The server's.",
			"Action.authorizedBy": "AuthorizedBy is the person who authorized it. The server's.",
			"Action.by":           "By is the user who filed this state. The server's.",
			"Action.decisionId":   "DecisionID is the DDT Action's decisionId. DERIVED by the server.",
			"Action.hash":         "Hash is this state's content hash, lowercase hex, over the DDT Action, the\nassignee and the authorization. Authorizing names it, so a person\nauthorizes the state they read. The server's.",
			"Action.id":           "ID is the action's record id, `act_` and 32 hex digits, one per DDT Action\nid. The server's.",
			"Action.status":       "Status is DRAFT until a person authorizes the action, then AUTHORIZED. The\nserver's: a write files DRAFT, and a DRAFT never replaces an AUTHORIZED\naction.",
			"Action.time":         "Time is when this state of the action was filed, RFC 3339 UTC. The\nserver's.",
			"authorizeIn.ID":      "ID is the action's record id, in the path.",
			"authorizeIn.hash":    "Hash is the hash of the state the person read: the action's `hash` as a\nlisting answered it. Required.",
		},
		Example: json.RawMessage(`{"hash":"5b0e1f0c2a8d4e6f9a1b3c5d7e9f1a2b5b0e1f0c2a8d4e6f9a1b3c5d7e9f1a2b"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research POST /v1/research/artifacts", zip.Doc{
		Description: "Records one research-diary artifact — a board snapshot,\nreport, manifest, harness, evidence, or result — CONTENT-ADDRESSED inside the trust\nboundary. The caller submits the bytes as base64 `content`; the SERVER hashes them\nand THAT hash is the identity and the ref, so the address can never be poisoned by\na client-asserted one. Client-supplied `sha256` or `content_sha256`, if present,\nmust match the bytes (422 otherwise). Empty `kind` defaults to `report`. Re-posting\nthe same bytes is a no-op that reports created=false.",
		Fields: map[string]string{
			"ResearchArtifact.artifact_id":       "ArtifactID is an optional producer-assigned logical identifier for the artifact\n(e.g. \"manifest-v1\" or \"rotten-tomatoes-predictions\").",
			"ResearchArtifact.canonicalization":  "Canonicalization names the byte-canonicalization scheme applied by the producer\nbefore hashing (e.g. \"rfc8785-jcs\" or \"utf8-lf\"), when applicable.",
			"ResearchArtifact.content":           "Content is the artifact's bytes, base64, on WRITE only, at most 16 MiB.\nNever returned: a read answers metadata and the address, and the bytes come\nfrom GET /v1/research/artifacts/{sha256}.",
			"ResearchArtifact.content_sha256":    "ContentSHA256 mirrors the server-verified SHA-256 hex digest of the raw bytes.\nIf supplied on write it must match the server-computed digest (422 otherwise);\nalways populated on stored and returned records.",
			"ResearchArtifact.git_branch":        "GitBranch is the branch that commit was on.",
			"ResearchArtifact.git_dirty":         "GitDirty says the working tree carried uncommitted changes.",
			"ResearchArtifact.git_sha":           "GitSHA is the commit that produced the artifact. Unlike a run's, an\nartifact's provenance is NOT part of its identity: the bytes are.",
			"ResearchArtifact.kind":              "Kind classifies the artifact: snapshot, report (default when omitted), artifact,\nevidence, harness, manifest, or result.",
			"ResearchArtifact.lib_versions":      "LibVersions is the libraries in force, as a JSON object of name → version.\nAbsent is {}.",
			"ResearchArtifact.media_type":        "MediaType is the MIME type of the stored bytes (e.g. \"application/json\",\n\"text/markdown\", \"image/png\"). Validated on write and served on blob reads\nwhen in the safe non-script allowlist.",
			"ResearchArtifact.project":           "Project is the project the artifact is filed under — the SERVER's value on\nwrite. It is part of the read predicate too: fetching a hash from the wrong\nproject is the same 404 as a hash that was never recorded.",
			"ResearchArtifact.received_at":       "ReceivedAt is the server wall-clock timestamp (unix seconds) stamped when\nthe artifact was first recorded. Ignored on write.",
			"ResearchArtifact.ref":               "Ref is the content address, \"sha256:<hash>\", composed by the server from\nthe same bytes. A ref sent in the body is discarded, so it can never name\nsomewhere else.",
			"ResearchArtifact.retention_class":   "RetentionClass is the retention bucket the bytes fall in. Every write is\nrecorded as raw-artifact — the class for material that may be personal or\nlicensed — so it is the server's word, not the caller's.",
			"ResearchArtifact.run_id":            "RunID is the experiment stable id this artifact belongs to, which is what\nthe diary feed's ?run= filters on. It is free text: nothing checks that the\nrun exists.",
			"ResearchArtifact.sha256":            "SHA256 is the SERVER's hash of the submitted bytes, hex, and the artifact's\nidentity — the key the blob route is addressed by. A caller MAY send one;\nit is not trusted, only checked, and a mismatch with the bytes refuses the\nwrite.",
			"ResearchArtifact.ts":                "TS is when the artifact was recorded, unix SECONDS — what the feed sorts\nnewest-first on and what ?since= is compared against. Defaults to ReceivedAt\nwhen 0 on write.",
			"ResearchArtifact.uncompressed_size": "UncompressedSize is the uncompressed byte length of the artifact; defaults to\nlen(rawBytes) on write when omitted or zero.",
			"ResearchArtifact.visibility":        "Visibility is private, org or public. A write forces private; only a grant\nby sha256 moves it.",
			"artifactOut.artifact_id":            "ArtifactID echoes the optional logical artifact identifier when supplied.",
			"artifactOut.content_sha256":         "ContentSHA256 echoes the server-verified SHA-256 hex digest of the raw bytes.",
			"artifactOut.created":                "Created is false when these exact bytes were already recorded — the write is a no-op.",
			"artifactOut.kind":                   "Kind is the normalized artifact kind recorded on the store (\"report\" when omitted).",
			"artifactOut.media_type":             "MediaType echoes the normalized MIME type when supplied.",
			"artifactOut.received_at":            "ReceivedAt is the server wall-clock timestamp (unix seconds) when the artifact was first stored.",
			"artifactOut.ref":                    "Ref is the content address, \"sha256:<hash>\".",
			"artifactOut.rolled_up":              "RolledUp is false when the OLAP roll-up was skipped; the SQLite write still stands.",
			"artifactOut.sha256":                 "SHA256 is the SERVER's hash of the bytes — the artifact's identity.",
			"artifactOut.uncompressed_size":      "UncompressedSize is the recorded uncompressed byte length.",
		},
		Example: json.RawMessage(`{"kind":"snapshot","content":"iVBORw0KGgo=","run_id":"benchmark:zen-1:mmlu"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research POST /v1/research/benchmarks", zip.Doc{
		Description: "Records benchmark definitions — the TASK a run is\nmeasured against, with its dataset, that dataset's licence and origin, its\ndeclared splits, its official metric and how to cite it. A definition is\nindependent of anyone's run and is recorded on its own: re-sending identical\ncontent appends nothing, and changing any of it appends a new version beside\nthe old one rather than replacing it.",
		Fields: map[string]string{
			"ResearchBenchmark.canonical": "Canonical is DERIVED on read, never stored: a version is canonical when\nit is the latest-appended non-retracted version of its id. A listing\nreturns only canonical versions, so it is true on every row it answers\nwith.",
			"ResearchBenchmark.citation":  "Citation is how to cite the task: the paper, the arXiv id, the\nrepository. A benchmark without one is a number nobody can check back to\na definition.",
			"ResearchBenchmark.dataset":   "Dataset is the items the benchmark draws on, named the way the reader\nfetches them: a Hugging Face path, a repository, a file.",
			"ResearchBenchmark.id":        "ID is the benchmark's stable id, lowercase and terse: locomo, mab,\nrepobench-r. It is what a Run's `benchmark` names and what versions of\nthis definition accrue under. Required on a write.",
			"ResearchBenchmark.license":   "License is the terms the DATASET comes under — CC BY-NC 4.0, MIT. Empty\nmeans the record does not say, which is not the same as permissive; a\nbenchmark whose licence is unrecorded is one nobody has checked.",
			"ResearchBenchmark.metric":    "Metric is the OFFICIAL metric — the one the benchmark's authors score it\nby and the one a comparison against published numbers has to use.",
			"ResearchBenchmark.metrics":   "Metrics are every quantity the benchmark's protocol reports, official\none included. A run may measure more; it may not measure fewer and still\nclaim the benchmark.",
			"ResearchBenchmark.notes":     "Notes is anything about the task a reader needs and the fields above do\nnot carry — that the released items are a proxy for an unreleased set,\nsay.",
			"ResearchBenchmark.origin":    "Origin is where the dataset was obtained: the URL or repository it was\nfetched from. Provenance for the items themselves, distinct from\nCitation, which is provenance for the task.",
			"ResearchBenchmark.project":   "Project is the sub-scope inside the org this definition is filed under.\nOn a write it is the SERVER's value — the caller's project scope — and a\nproject sent in the body is ignored.",
			"ResearchBenchmark.revision":  "Revision is this version's declared kind: original, corrected or\nretracted. Anything else, including empty, reads as original. A retracted\nlatest version WITHDRAWS the id; every earlier version stays retained.",
			"ResearchBenchmark.splits":    "Splits are the divisions the benchmark declares, each with its own\ndefinition. A run names one of these in its `split`.",
			"ResearchBenchmark.title":     "Title is the benchmark's published name, as its authors write it.",
			"ResearchBenchmark.version":   "Version is the benchmark's OWN revision — v6, 2025-03 — not the version\nof anything that ran it. Empty means the benchmark publishes none.",
			"ResearchBenchmark.when":      "When is when this definition was recorded, RFC3339. Empty means the\nrecord does not say.",
			"Split.definition":            "Definition is the split in the benchmark's own words — \"conversations 0,\n1 and 2\", \"the 32k, 64k and 262k haystacks\". It is what makes a split\nreproducible by someone who has only the dataset, so a split named\nwithout one is a label rather than a definition.",
			"Split.items":                 "Items is how many of the benchmark's items the split holds. 0 means the\ndefinition does not state a size.",
			"Split.name":                  "Name is what the benchmark calls this division: dev, test, all.",
			"benchmarkBatch.benchmarks":   "Benchmarks are the definitions to record. Each needs an id. At most\n20000 in one call.",
			"recordBatch.canonical":       "Canonical is how many distinct records of this kind the store now holds\n— the deduped view, retractions withdrawn.",
			"recordBatch.project":         "Project is the project the batch was filed under — the SERVER's value,\nnever the body's.",
			"recordBatch.recorded":        "Recorded is how many NEW versions this call appended. Zero on a\nbyte-identical re-send, which is what makes a backfill replayable.",
		},
		Example: json.RawMessage(`{"benchmarks":[{"id":"locomo","title":"LoCoMo","dataset":"snap-research/locomo","license":"CC BY-NC 4.0","metric":"f1"}]}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/research POST /v1/research/candidates", zip.Doc{
		Description: "Records a new EvolutionCandidate node in the\nevolutionary lineage DAG (HIP-1401 §§1–2). Mutations outside the five\npermitted surfaces (such as sandbox isolation, audit hashing, or evaluation\ngates) are deterministically rejected 422. Every new candidate enters as\nproposed and requires independent qualification to earn XP or promote.",
		Fields: map[string]string{
			"AttributionShare.principal":           "Principal is the contributing human or agent identity (did:hanzo:... or user id).",
			"AttributionShare.weight":              "Weight is this contributor's fractional share; shares across a record sum to 1.0.",
			"CandidateAttestation.attested_at":     "AttestedAt is the RFC 3339 UTC timestamp when the attestation was recorded.",
			"CandidateAttestation.evidence_ref":    "EvidenceRef is the content-addressed Evidence or Run digest verified.",
			"CandidateAttestation.role":            "Role names the attestation stage: harness, qualifier, or promoter.",
			"CandidateAttestation.signature":       "Signature is the optional cryptographic signature (ed25519:...) over candidate_id.",
			"CandidateAttestation.verifier":        "Verifier is the independent principal attesting to the candidate's evaluation.",
			"EvolutionCandidate.artifact_digest":   "ArtifactDigest is the content-addressed digest (sha256:...) of the mutated\nartifact bundle.",
			"EvolutionCandidate.attestations":      "Attestations lists independent verification and qualification attestations.",
			"EvolutionCandidate.candidate_id":      "CandidateID is the sha256:<hex> digest of the canonical candidate payload\n(excluding signature, attestations, and mutable lifecycle fields).",
			"EvolutionCandidate.contributors":      "Contributors holds fractional attribution shares summing to 1.0 for XP projection.",
			"EvolutionCandidate.created_at":        "CreatedAt is the RFC 3339 UTC timestamp when the candidate was proposed.",
			"EvolutionCandidate.diff_ref":          "DiffRef is the content-addressed unified diff or patch bundle against parent_ids[0].",
			"EvolutionCandidate.evidence_refs":     "EvidenceRefs lists content-addressed Evidence or Run digests produced by\nevaluating this candidate.",
			"EvolutionCandidate.evolution_fitness": "EvolutionFitness holds optional Level 2 meta-evolutionary yield and lift metrics.",
			"EvolutionCandidate.gate_ref":          "GateRef names the evaluation benchmark or conformance suite version gating\nthis candidate.",
			"EvolutionCandidate.mutation_surface":  "MutationSurface names the single permitted architectural surface modified:\nharness.policy, engine.strategy, router.cascade, model.adapter, or research.protocol.",
			"EvolutionCandidate.parent_ids":        "ParentIDs lists one or more parent candidate_ids (or [\"root\"] for genesis\nbaselines), forming a directed acyclic lineage graph.",
			"EvolutionCandidate.product_fitness":   "ProductFitness holds the Level 1 multi-objective task metrics once evaluated.",
			"EvolutionCandidate.project":           "Project is the sub-scope inside the org this candidate belongs to, set by\nthe server on write.",
			"EvolutionCandidate.proposer":          "Proposer is the principal (did:hanzo:... or IAM user) proposing the candidate.",
			"EvolutionCandidate.qualified_at":      "QualifiedAt is the RFC 3339 UTC timestamp when the candidate was qualified.",
			"EvolutionCandidate.qualified_by":      "QualifiedBy is the independent principal who qualified or promoted the candidate.",
			"EvolutionCandidate.retracted_by":      "RetractedBy holds the CounterEvidence digest when status is retracted.",
			"EvolutionCandidate.rollback_target":   "RollbackTarget is the pinned parent candidate_id or artifact digest preserved\nfor instant rollback on promotion (HIP-1401 §5.2).",
			"EvolutionCandidate.seq":               "Seq is the store's monotone append sequence number for this version.",
			"EvolutionCandidate.signature":         "Signature is the proposer's optional cryptographic signature over candidate_id.",
			"EvolutionCandidate.spec_version":      "SpecVersion is the target Hanzo OS standard.json semantic version (for\nexample \"1.0.0\").",
			"EvolutionCandidate.status":            "Status is proposed, qualified, promoted, retired, or retracted.",
			"EvolutionCandidate.was_qualified":     "WasQualified records whether this candidate passed independent qualification\nbefore any subsequent retraction, enabling exact XP reversal.",
			"EvolutionFitness.discovery_rate":      "DiscoveryRate is the fraction of generated child candidates that pass\nindependent holdout qualification.",
			"EvolutionFitness.reproducibility":     "Reproducibility is 1.0 minus variance across independent clean-room reruns\nin [0.0, 1.0].",
			"EvolutionFitness.research_yield":      "ResearchYield is verified fitness delta achieved per US dollar of compute spent.",
			"EvolutionFitness.successor_lift":      "SuccessorLift is the best verified fitness improvement over parent lineage\nwithin a fixed compute horizon.",
			"EvolutionFitness.transfer_rate":       "TransferRate is the fraction of improvements on source tasks that transfer\nwithout regression to out-of-distribution target tasks.",
			"ProductFitness.cost_per_success_usd":  "CostPerSuccessUSD is total token plus sandbox compute spend in US dollars\nper verified task success (minimize).",
			"ProductFitness.latency_p50_ms":        "LatencyP50Ms is median wall-clock task completion latency in milliseconds (minimize).",
			"ProductFitness.latency_p95_ms":        "LatencyP95Ms is 95th-percentile wall-clock task completion latency in milliseconds (minimize).",
			"ProductFitness.robustness":            "Robustness is the pass rate under adversarial perturbation and environment\nvariation in [0.0, 1.0] (maximize).",
			"ProductFitness.safety":                "Safety is 1.0 minus the policy/sandbox violation rate in [0.0, 1.0]; must\nequal 1.0 (zero violations) for qualification.",
			"ProductFitness.verified_success":      "VerifiedSuccess is the pass rate on deterministic conformance and holdout\nsuites in [0.0, 1.0] (maximize).",
		},
		Example: json.RawMessage(`{"parent_ids":["root"],"spec_version":"1.0.0","mutation_surface":"engine.strategy","artifact_digest":"sha256:9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08","diff_ref":"sha256:deadbeef","gate_ref":"swe-bench-verified@1.2.0"}`),
	})
