	zip.Describe("github.com/hanzoai/cloud/apps/research POST /v1/research/claims", zip.Doc{
		Description: "Records a scientific claim backed by a completed Run\n(HIP-1403 §1.2 & §3). A confirmatory claim MUST reference an existing\nHypothesisRecord whose sequence number strictly precedes the supporting Run's\nsequence number, and begins in the unreplicated state.",
		Fields: map[string]string{
			"AttributionShare.principal":     "Principal is the contributing human or agent identity (did:hanzo:... or user id).",
			"AttributionShare.weight":        "Weight is this contributor's fractional share; shares across a record sum to 1.0.",
			"ClaimReplication.agreed":        "Agreed reports whether the replication satisfied directional and interval\nagreement with the primary claim.",
			"ClaimReplication.confidence_hi": "ConfidenceHi is the optional upper confidence bound reported by the replication run.",
			"ClaimReplication.confidence_lo": "ConfidenceLo is the optional lower confidence bound reported by the replication run.",
			"ClaimReplication.replicated_at": "ReplicatedAt is the RFC 3339 UTC server timestamp when this replication was recorded.",
			"ClaimReplication.run_id":        "RunID is the completed independent Run that reproduced the primary claim.",
			"ClaimReplication.value":         "Value is the measured value observed on the replication run for the claim's metric.",
			"ClaimReplication.verifier":      "Verifier is the independent principal (distinct from the claim's proposer)\nwho executed and filed this replication.",
			"CounterEvidence.evidence_ref":   "EvidenceRef is the content-addressed Evidence or artifact digest (sha256:...\nor ev_...) demonstrating the refutation or regression.",
			"CounterEvidence.filed_at":       "FiledAt is the RFC 3339 UTC server timestamp when the retraction was recorded.",
			"CounterEvidence.filed_by":       "FiledBy is the principal who submitted the counter-evidence.",
			"CounterEvidence.run_id":         "RunID is the optional completed Run ID whose negative or contradictory\nmeasurement refuted the claim.",
			"CounterEvidence.summary":        "Summary states concisely how the prior claim or candidate failed verification.",
			"ResearchClaim.candidate_ref":    "CandidateRef is the optional EvolutionCandidate digest (sha256:...) evaluated\nby this claim.",
			"ResearchClaim.claim_id":         "ClaimID is the content-addressed sha256:<hex> identity of the claim's core\nassertion, computed by the server.",
			"ResearchClaim.confidence_hi":    "ConfidenceHi is the optional upper confidence interval bound for Value.",
			"ResearchClaim.confidence_lo":    "ConfidenceLo is the optional lower confidence interval bound for Value.",
			"ResearchClaim.contributors":     "Contributors holds optional multi-principal attribution shares summing to 1.0.",
			"ResearchClaim.counter_evidence": "CounterEvidence holds the refutation record when status is retracted.",
			"ResearchClaim.created_at":       "CreatedAt is the RFC 3339 UTC timestamp when the claim was first filed.",
			"ResearchClaim.effect_size":      "EffectSize is the directional delta over the baseline or null threshold.",
			"ResearchClaim.evidence_refs":    "EvidenceRefs lists content-addressed Evidence or artifact digests backing the claim.",
			"ResearchClaim.hypothesis_id":    "HypothesisID is the pre-registered HypothesisRecord (sha256:...) this claim\ntests; required when mode is confirmatory.",
			"ResearchClaim.metric":           "Metric names the measured quantity on the primary and replication runs.",
			"ResearchClaim.mode":             "Mode is confirmatory (pre-registered before execution) or exploratory\n(post-hoc observation, ineligible for confirmatory promotion or XP).",
			"ResearchClaim.project":          "Project is the sub-scope inside the org this claim belongs to, set by the\nserver on write.",
			"ResearchClaim.proposer":         "Proposer is the principal filing the claim.",
			"ResearchClaim.replications":     "Replications lists independent replication attempts recorded against this claim.",
			"ResearchClaim.run_id":           "RunID is the completed primary Run ID supporting this claim.",
			"ResearchClaim.seq":              "Seq is the store's monotone append sequence number for this version.",
			"ResearchClaim.status":           "Status is unreplicated, replicated, or retracted — derived and enforced by\nthe server's verification state machine.",
			"ResearchClaim.updated_at":       "UpdatedAt is the RFC 3339 UTC timestamp of the latest state transition.",
			"ResearchClaim.value":            "Value is the primary run's measured value on Metric, derived from the run\nrecord when present.",
			"ResearchClaim.was_replicated":   "WasReplicated records whether this claim ever achieved independent\nreplication prior to a retraction, so XP reversal is auditable.",
		},
		Example: json.RawMessage(`{"hypothesis_id":"sha256:...","run_id":"swe-verified-cand-1","mode":"confirmatory","metric":"pass@1","effect_size":0.042}`),
	})
